"""Write the human-readable result from completed, explicitly reviewed runs."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text())
def main():
    audit=read(ROOT/'optimizer-audit.json');comparison=read(ROOT/'comparison.json');chosen=comparison['candidate']['run'];test=read(ROOT/chosen/'test.json');review=read(ROOT/chosen/'review-test.json')
    lines=['# 原文日本語の再学習結果','',f"原文の語彙比較2,000更新、本学習10,000更新、追加の原文学習10,000更新を実行し、合計{audit['totalCompletedCleanRawUpdates']:,}回のoptimizer更新を完了した。6層モデルの系譜と、別初期化のpilotの更新は区別する。速度比較の60更新は全て破棄し、この数に入れない。",'',f"固定した未見TEST24件で、選択モデル `{chosen}` の自然な一文の合格は **{review['passed']}/24**。言語段階の判定は **{'合格' if review['gatePassed'] else '不合格'}**。損失の低下や更新数だけを日本語生成能力の達成とは扱わない。",'','## 実際に保存した学習','', '| run | 完了更新 | 選択更新 | パラメーター | canonical VAL NLL/byte |','| --- | ---: | ---: | ---: | ---: |']
    for run in audit['runs']:lines.append(f"| {run['run']} | {run['completedOptimizerUpdates']:,} | {run['selectedStep']:,} | {run['parameters']:,} | {run['bestCanonicalValidationNllPerUtf8Byte']:.6f} |")
    lines+=['',f"追加モデルは自作の本学習checkpointのみを読み込み、optimizerと乱数seedをリセット。選択した追加モデル重みの系譜は親の選択更新＋追加の選択更新で{audit['selectedChildWeightLineageUpdates']:,}更新。各runの最後のoptimizer/RNGと、VALで選んだbeststateは別に保存している。",'', '5,000更新の中間診断は本学習・追加学習ともVAL9件中1件合格だった。これは各runの途中の重みであり、新しい5,000更新を追加で実行した意味ではない。全token、元の出力、採点、gzipの実物重みとSHAを保存する。', '', '## 未見の同じ書き出しでの比較','', '| モデル・グループ | 一文合格 | 全文で反復ループなし | 判定 |','| --- | ---: | ---: | --- |']
    for label,key in [('旧原文モデル','baseline'),('選択モデル','candidate')]:
        for name,g in comparison[key]['groups'].items():lines.append(f"| {label} / {name} | {g['firstSentencePassed']}/{g['total']} | {g['fullOutputNonLoop']}/{g['total']} | {'合格' if g['gatePassed'] else '不合格'} |")
    likelihood=test['likelihood']
    lines+=['', f"選択モデルのcanonical TESTはNLL/UTF-8 byte={likelihood['nllPerUtf8Byte']:.6f}、token perplexity={likelihood['tokenPerplexity']:.3f}。原文の完全段落を使い、旧モデルと同じTEST損失を比較した値ではない。", '', '文学8件・情報通信8件・環境8件をTokenizer学習前に固定し、以前の結果を見た文書とTRAINの書き出しを除外。旧原文モデルにもこの書き出しの文書・prefixのTRAIN混入はない。canonical VAL byte損失で最終候補を先に固定してからTESTを生成した。語の途中のBPE境界と元の表記を追加する判断には開発VALを使ったが、TESTの文書・基準・greedy decoding・語彙・heldデータは変更していない。', '', '文法・意味・書き出しとの接続・反復・破綻を各0〜2点で手動採点。9点以上、文法2、接続2、文が閉じること、有効なtokenが条件。文学／現代説明文のそれぞれで一文合格80%以上、全文の非ループ90%以上が必要。採点者はアシスタントであり、独立した人によるblind評価ではない。原文の続きとの完全一致を正解としない。生成された統計・固有名詞・法律・事実の正確性は言語採点から保証しない。', '', '全語彙のgreedy自己回帰生成、BOS＋元の書き出し、最大128新token、EOS／contextで終了する。外部API・検索・固定文・文法修正・反復penaltyで補わない。Pythonと独自JSで全件の文章・全token・EOS・有効性を比較し、全文一致を確認。全logitの参照誤差も2e-4以下。', '', '今回のTEST24件は以後は開発診断用になる。さらに改善する場合は未使用文書から新規TESTを用意する。今回の比較はデータ、語彙、規模、更新数が変わっており、一つの変更だけの因果効果や広い会話能力の証明ではない。', '', '## データ・速度・再現性', '', '新規の現代日本語は571文書、1,276,513文字。既存を含め1,014文書、4,190,519文字。出典・取得・利用条件・原文SHAを保持し、総務省／環境省の公共データ利用規約に沿って本文を加工した。同じ段落が複数年度にあるため、新規文書の80文字以上の一致段落を同じ分割へ置く。新規の長い段落の分割間重複は0件。過去から開示されているMDNの共有段落1件は保持し、過去の分割と206ファイルのSHAは変更しない。', '', '独自byte-BPEはTRAIN原文だけで学習。追加prefix-viewは同じ原文の73,760個の再符号化で、新たな文章・QA・teacherデータではない。四つのUnicode切断位置でprefix/suffixを別々に符号化し、原文の全角空白も保持。内部にEOSや区切りを入れず、heldデータと語彙はbyte単位で同一。', '', 'CPU2コア・8 GiB、PyTorch2.6.0+cpu、CUDAなし。固定256token/batch8のABBA比較ではFP32中央値0.544091秒に対しBF16は0.365415秒。activationのみBF16、重み・optimizer・検証・最終推論はFP32。同じ形状の計算比較で、サイトの回答速度や生成品質の改善を証明する値ではない。長さ別batchは対象tokenと周辺分布を保つが、batch内の相関・更新軌跡は異なる。', '', '各runにcheckpoint、optimizer、Python／Torch RNG、settings、history、選択beststate、FP32のJS exportを保存。pilotは実行時にtrainer SHAをcheckpointへ保存していなかったため、当時のコードコピーのSHAを事後に記録した。本学習／追加学習は実行時のtrainer SHAも照合した。', '', '参照：`optimizer-audit.json`、`checkpoint-choice.json`、`comparison.json`、`reproducibility-manifest.json`、各runの採点JSON、`raw-modern-million/learning-curves.svg`。以前の実験は独立した記録として保持する。', '', '## 公開と次の段階', '', '言語段階の未達を質問回答やinstruction学習で隠さず、QAは再開していない。公開サイトのプロフィール回答モデルは比較用に保持し、この原文候補へ置き換えていない。今回の成果は出典付きデータ、実物モデル、再現手順と未見評価をリポジトリへ保存したこと。幅広く自然に会話できる能力を達成したとは扱わない。次に検証する候補は `NEXT.md` に記録する。','']
    (ROOT/'RESULTS.md').write_text('\n'.join(lines))
if __name__=='__main__':main()
